mapper.select:
SELECT co.CONT_NO ,co.CONT_SEQ ,co.ORG_NO ,om.ORG_CD ,co.BRCH_POLICY_TYPE_CD ,co.SAVE_CAN_YN ,co.USE_CAN_YN ,co.CONT_ORG_STS_CD ,co.TOTAL_ISU_ABLE_CNT ,co.TOTAL_ISU_ABLE_PT ,co.REG_USER_ID ,co.REG_DT ,co.LAST_MOD_USER_ID ,co.LAST_MOD_DT FROM T_CONT_ORG co INNER JOIN T_ORG_MST om ON om.ORG_NO = co.ORG_NO WHERE 1 = 1
AND co.CONT_NO = #{contNo}
AND co.CONT_SEQ = #{contSeq}
AND co.ORG_NO = #{orgNo}
AND om.ORG_CD = #{orgCd}

SELECT
COUNT(*)
FROM CONT_ORG co
    INNER JOIN T_ORG_MST om ON om.ORG_NO = co.ORG_NO
WHERE 1 = 1

    AND co.CONT_NO = #{contNo}


    AND co.CONT_SEQ = #{contSeq}


    AND co.ORG_NO = #{orgNo}


    AND om.ORG_CD = #{orgCd}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY co.CONT_NO, co.CONT_SEQ, co.ORG_NO) ROW_NUM ,co.CONT_NO ,co.CONT_SEQ ,co.ORG_NO ,om.ORG_CD ,co.BRCH_POLICY_TYPE_CD ,co.SAVE_CAN_YN ,co.USE_CAN_YN ,co.CONT_ORG_STS_CD ,co.TOTAL_ISU_ABLE_CNT ,co.TOTAL_ISU_ABLE_PT ,co.REG_USER_ID ,co.REG_DT ,co.LAST_MOD_USER_ID ,co.LAST_MOD_DT FROM T_CONT_ORG co INNER JOIN T_ORG_MST om ON om.ORG_NO = co.ORG_NO WHERE 1 = 1
AND co.CONT_NO = #{contNo}
AND co.CONT_SEQ = #{contSeq}
AND co.ORG_NO = #{orgNo}
AND om.ORG_CD = #{orgCd}
ORDER BY co.CONT_NO, co.CONT_SEQ, co.ORG_NO ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
